<?php
// Tampilan bersama untuk data guru dan pengurus. Dipanggil dari guru.php / pengurus.php.
$cfg=master_config($module);$table=$cfg['table'];$title=$cfg['title'];$fields=$cfg['fields'];$statuses=$cfg['statuses'];
$edit=null;
if(query('edit')!=='' && can_write($module)) { $edit=sql('SELECT * FROM '.$table.' WHERE id=?',[query('edit')])->fetch();if(!$edit) echo '<p class="error">Data tidak ditemukan.</p>'; }
$search=query('q');$n=max(1,(int)query('n','1'));$like='%'.$search.'%';
$where=' WHERE nama LIKE ? OR kode LIKE ?';
$count=(int)sql('SELECT COUNT(*) FROM '.$table.$where,[$like,$like])->fetchColumn();$pages=max(1,(int)ceil($count/25));$n=min($n,$pages);$offset=($n-1)*25;
$rows=sql('SELECT * FROM '.$table.$where.' ORDER BY id DESC LIMIT 25 OFFSET '.$offset,[$like,$like]);
?><h1>Data <?=esc($title)?></h1><?php if(can_write($module)): ?><section class="card"><h2><?=$edit?'Edit':'Tambah'?> <?=esc($title)?></h2><form method="post"><?php token(); ?><input type="hidden" name="id" value="<?=esc($edit['id']??'')?>"><div class="formgrid"><?php foreach($fields as $key=>[$label,$max]): ?><label><?=esc($label)?><input name="<?=esc($key)?>" maxlength="<?=$max?>" value="<?=esc($edit[$key]??'')?>" <?=in_array($key,['nama','kode'],true)?'required':''?>></label><?php endforeach; ?><label>Status<select name="status"><?php foreach($statuses as $s): ?><option value="<?=esc($s)?>" <?=($edit['status']??$statuses[0])===$s?'selected':''?>><?=esc($s)?></option><?php endforeach; ?></select></label></div><button name="action" value="save_<?=esc($module)?>">Simpan</button> <a href="?page=<?=esc($module)?>">Batal / Form Baru</a></form></section><?php endif; ?><section class="card"><h2>Daftar <?=esc($title)?></h2><form method="get" class="search"><input type="hidden" name="page" value="<?=esc($module)?>"><label>Cari nama atau kode<input name="q" value="<?=esc($search)?>"></label><button>Cari</button></form><p><?=$count?> data</p><div class="tablewrap"><table><thead><tr><?php foreach($fields as [$label]): ?><th><?=esc($label)?></th><?php endforeach; ?><th>Status</th><?php if(can_write($module)): ?><th>Aksi</th><?php endif; ?></tr></thead><tbody><?php foreach($rows as $r): ?><tr><?php foreach($fields as $key=>$_): ?><td><?=esc($r[$key])?></td><?php endforeach; ?><td><?=esc($r['status'])?></td><?php if(can_write($module)): ?><td><a href="?page=<?=esc($module)?>&amp;edit=<?=(int)$r['id']?>">Edit</a></td><?php endif; ?></tr><?php endforeach; ?><?php if(!$count): ?><tr><td colspan="<?=count($fields)+2?>">Belum ada data yang sesuai.</td></tr><?php endif; ?></tbody></table></div><div class="pager"><?php if($n>1): ?><a href="?<?=esc(http_build_query(['page'=>$module,'q'=>$search,'n'=>$n-1]))?>">Sebelumnya</a><?php endif; ?><span>Halaman <?=$n?> / <?=$pages?></span><?php if($n<$pages): ?><a href="?<?=esc(http_build_query(['page'=>$module,'q'=>$search,'n'=>$n+1]))?>">Berikutnya</a><?php endif; ?></div></section>
